export function buildReceipt({fileName,sha256,report,graph,seed,post,destroyKey}){return{schema:"ticket-v1",generated:new Date().toISOString().slice(0,19).replace("T"," ")+" UTC",file:{name:fileName,sha256},summary:{systems:report.totals.systems,events:report.totals.events,regions:report.totals.regions,named_planets:report.totals.named_planets,galaxies:report.totals.galaxies,period:report.period,birth:report.birth,teleports:report.trajectory.teleports.length,bases:report.trajectory.bases.length,beats:graph.beats.map(b=>b.type)},seed,destroy_key:destroyKey??null,post_encoding:post?post.encoding:null,post_bytes:post?JSON.stringify(post).length:0}}
